import{c as e,Z as o,Q as u,j as r,m as q,o as t}from"./chunks/framework.DOi4mjdC.js";const f=JSON.parse('{"title":"九歌·东君","description":"","frontmatter":{"title":"九歌·东君","author":"屈原","dynasty":"战国"},"headers":[],"relativePath":"books/shici/chuci/6.md","filePath":"books/shici/chuci/6.md"}'),n={name:"books/shici/chuci/6.md"};function s(h,i,p,c,d,_){const l=o("PoemAuthor"),a=o("PoemNav");return u(),r("div",null,[i[0]||(i[0]=q('<h1 id="九歌·东君" tabindex="-1">九歌·东君 <a class="header-anchor" href="#九歌·东君" aria-label="Permalink to &quot;九歌·东君&quot;">​</a></h1><p><strong>[战国] <a href="/authors/quyuan.html">屈原</a></strong></p><h2 id="原文" tabindex="-1">原文 <a class="header-anchor" href="#原文" aria-label="Permalink to &quot;原文&quot;">​</a></h2><p>暾将出兮东方，照吾槛兮扶桑。抚余马兮安驱，夜皎皎兮既明。驾龙辀兮乘雷，载云旗兮委蛇。长太息兮将上，心低徊兮顾怀。羌声色兮娱人，观者憺兮忘归。</p><p>緪瑟兮交鼓，箫钟兮瑶虡。鸣篪兮吹竽，思灵保兮贤姱。翾飞兮翠曾，展诗兮会舞。应律兮合节，灵之来兮蔽日。</p><p>青云衣兮白霓裳，举长矢兮射天狼。操余弧兮反沦降，援北斗兮酌桂浆。撰余辔兮高驼翔，杳冥冥兮以东行。</p><h2 id="注释" tabindex="-1">注释 <a class="header-anchor" href="#注释" aria-label="Permalink to &quot;注释&quot;">​</a></h2><ul><li>东君：太阳神</li><li>暾：初升的太阳</li><li>槛：栏杆</li><li>扶桑：神话中太阳升起的地方</li><li>皎皎：明亮</li><li>辀：车辕</li><li>委蛇：蜿蜒曲折</li><li>低徊：徘徊</li><li>顾怀：眷恋</li><li>羌：发语词</li><li>憺：安然，沉醉</li><li>緪：张紧琴弦</li><li>交鼓：交替击鼓</li><li>箫钟：击钟</li><li>瑶虡：玉饰的钟架</li><li>篪：古代乐器</li><li>灵保：巫师</li><li>贤姱：美好</li><li>翾飞：轻快地飞舞</li><li>翠曾：翠鸟展翅</li><li>应律：合乎音律</li><li>合节：合乎节拍</li><li>天狼：天狼星，象征灾祸</li><li>弧：弓</li><li>沦降：降落</li><li>援：拿起</li><li>桂浆：桂花酒</li><li>撰：握住</li><li>辔：马缰绳</li><li>杳冥冥：昏暗</li></ul><h2 id="译文" tabindex="-1">译文 <a class="header-anchor" href="#译文" aria-label="Permalink to &quot;译文&quot;">​</a></h2><p>太阳将从东方升起，照耀着我的栏杆和扶桑。安抚我的马缓缓前行，夜色渐明，天已破晓。驾着龙车乘着雷声，载着云旗蜿蜒前行。长叹一声将要上升，心中徘徊眷恋。那美妙的声色使人愉悦，观看的人沉醉忘归。</p><p>张紧瑟弦交替击鼓，敲击玉钟，吹奏篪竽，思念那美好的巫师。像翠鸟一样轻快地飞舞，展开诗篇合着舞蹈。合乎音律合乎节拍，神灵到来遮蔽了太阳。</p><p>穿着青云衣白霓裳，举起长箭射向天狼。拿起我的弓返回降落，拿起北斗酌饮桂花酒。握住马缰高高飞翔，在昏暗中东行而去。</p><h2 id="赏析" tabindex="-1">赏析 <a class="header-anchor" href="#赏析" aria-label="Permalink to &quot;赏析&quot;">​</a></h2><p>这首诗是《九歌》中的一篇，是祭祀太阳神的乐歌，描写了太阳东升西落的运行过程，以及祭祀时的歌舞场面。</p><p>第一段写太阳升起。&quot;暾将出兮东方&quot;，写太阳从东方升起。&quot;照吾槛兮扶桑&quot;，写太阳照耀着扶桑。&quot;抚余马兮安驱&quot;，写太阳神安抚马匹缓缓前行。&quot;夜皎皎兮既明&quot;，写夜色渐明，天已破晓。</p><p>接着写太阳神的威仪。&quot;驾龙辀兮乘雷&quot;，写太阳神驾龙车、乘雷声。&quot;载云旗兮委蛇&quot;，写云旗蜿蜒。&quot;长太息兮将上&quot;，写太阳神长叹一声将要上升。&quot;羌声色兮娱人&quot;，写祭祀时的歌舞使人愉悦。</p><p>第二段写祭祀的歌舞。&quot;緪瑟兮交鼓&quot;，写瑟鼓齐鸣。&quot;箫钟兮瑶虡&quot;，写钟鼓齐奏。&quot;鸣篪兮吹竽&quot;，写各种乐器合奏。&quot;翾飞兮翠曾&quot;，写舞者像翠鸟一样飞舞。&quot;应律兮合节&quot;，写歌舞合乎音律节拍。</p><p>第三段写太阳西落。&quot;青云衣兮白霓裳&quot;，写太阳神的服饰。&quot;举长矢兮射天狼&quot;，写太阳神射天狼星，象征驱除灾祸。&quot;操余弧兮反沦降&quot;，写太阳神返回降落。&quot;援北斗兮酌桂浆&quot;，写太阳神拿起北斗酌酒。&quot;杳冥冥兮以东行&quot;，写太阳在昏暗中东行，准备第二天的升起。</p><p>全诗想象丰富，气势磅礴，将太阳神的威仪和祭祀的盛况描绘得如诗如画。</p>',19)),t(l,{name:"屈原",years:"约公元前340年－公元前278年",desc:"名平，字原，战国时期楚国诗人、政治家。中国浪漫主义文学的奠基人，“楚辞”的创立者和代表作家。代表作有《离骚》《九歌》《天问》等。",link:"/authors/quyuan"}),t(a)])}const b=e(n,[["render",s]]);export{f as __pageData,b as default};
